// lib module colormap@1 (design/programmable-graphics.md, Lib Modules): the
// host's colormaps. A piece that imports it calls colormap::sample,
// colormap::viridis or colormap::magma. Released; never changes.

// The rows of caliper_colormaps.
const colormap__VIRIDIS: u32 = 0u;
const colormap__MAGMA: u32 = 1u;
const colormap__RDBU: u32 = 2u;
const colormap__GREYS: u32 = 3u;

// The color of t, from 0 to 1, on a host colormap, linear between its texels.
fn colormap__sample(map: u32, t: f32) -> vec4<f32> {
    let size = textureDimensions(caliper_colormaps);
    let row = i32(min(map, size.y - 1u));
    let x = clamp(t, 0.0, 1.0) * f32(size.x - 1u);
    let x0 = i32(floor(x));
    let x1 = min(x0 + 1, i32(size.x) - 1);
    let a = textureLoad(caliper_colormaps, vec2<i32>(x0, row), 0);
    let b = textureLoad(caliper_colormaps, vec2<i32>(x1, row), 0);
    return mix(a, b, x - f32(x0));
}

fn colormap__viridis(t: f32) -> vec4<f32> {
    return colormap__sample(colormap__VIRIDIS, t);
}

fn colormap__magma(t: f32) -> vec4<f32> {
    return colormap__sample(colormap__MAGMA, t);
}
// lib module pick@1 (design/programmable-graphics.md, Lib Modules): the ID
// that a pick pass writes and the linked selection. A piece that imports it
// calls pick::id, pick::selected and pick::selected_index. Released; never
// changes.

// The ID that a pass with pick = true writes at location 1: the program's
// pick id and the item, an element index of the item map's resource.
fn pick__id(item: u32) -> vec2<u32> {
    return vec2<u32>(caliper_view.frame.z, item);
}

// The count of valid entries of caliper_selection.
fn pick__selection_count() -> u32 {
    return min(caliper_view.frame.w, min(arrayLength(&caliper_selection), 256u));
}

// Whether an item of this program is in the linked selection.
fn pick__selected(item: u32) -> bool {
    let n = pick__selection_count();
    for (var i = 0u; i < n; i = i + 1u) {
        let s = caliper_selection[i];
        if (s.pick == caliper_view.frame.z && s.item == item) {
            return true;
        }
    }
    return false;
}

// Whether a selected item of any program has these tensor indices; an index
// below 0 matches every index.
fn pick__selected_index(index: vec4<i32>) -> bool {
    let n = pick__selection_count();
    for (var i = 0u; i < n; i = i + 1u) {
        let s = caliper_selection[i].index;
        if (all((index == s) | (index < vec4<i32>(0)))) {
            return true;
        }
    }
    return false;
}
// lib module camera@1 (design/programmable-graphics.md, Lib Modules): clip
// positions and offsets in pixels from the host camera. A piece that imports
// it calls camera::clip, camera::pixel_direction and camera::offset_pixels.
// Released; never changes.

// The clip position of a world position.
fn camera__clip(world: vec3<f32>) -> vec4<f32> {
    return caliper_view.clip_from_world * vec4<f32>(world, 1.0);
}

// The unit direction in pixels from clip position a to clip position b, or
// (1, 0) when they fall on one pixel.
fn camera__pixel_direction(a: vec4<f32>, b: vec4<f32>) -> vec2<f32> {
    let d = (b.xy / b.w - a.xy / a.w) * caliper_view.viewport.zw;
    let n = length(d);
    if (n < 1e-6) {
        return vec2<f32>(1.0, 0.0);
    }
    return d / n;
}

// A clip position moved by a distance in pixels on the screen.
fn camera__offset_pixels(clip: vec4<f32>, pixels: vec2<f32>) -> vec4<f32> {
    return clip + vec4<f32>(pixels * 2.0 / caliper_view.viewport.zw * clip.w, 0.0, 0.0);
}
// Shared layout constants for the 10-digit MNIST accuracy ring.
const CLASSES: u32 = 10u;
const RING_R: f32 = 0.85;
const BASE_Y: f32 = -0.65;

fn digit_angle(digit: u32) -> f32 {
    return 6.2831853 * f32(digit) / f32(CLASSES);
}

fn ring_pos(digit: u32, radius: f32, y: f32) -> vec3<f32> {
    let a = digit_angle(digit);
    return vec3<f32>(radius * cos(a), y, radius * sin(a));
}

