// Compute per-digit probe accuracy, error count, and mean true-class probability on GPU.
@compute @workgroup_size(10)
fn compute_metrics(@builtin(global_invocation_id) id: vec3<u32>) {
    let d = id.x;
    if (d >= CLASSES) {
        return;
    }
    let n_log = shapes.logits.z;
    let c_log = shapes.logits.w;
    let n_tgt = shapes.targets.w;
    let n = min(n_log, n_tgt);
    if (n == 0u || c_log < CLASSES) {
        metrics[d] = DigitMetric(d, 0u, 0u, 0u, 0u, 0.0, 0.0);
        return;
    }
    var total = 0u;
    var correct = 0u;
    var conf_sum = 0.0;
    for (var i = 0u; i < n; i = i + 1u) {
        if (targets[i] == i32(d)) {
            total = total + 1u;
            let base = i * c_log;
            var best = 0u;
            var best_val = logits[base];
            for (var c = 1u; c < CLASSES; c = c + 1u) {
                let v = logits[base + c];
                if (v > best_val) {
                    best_val = v;
                    best = c;
                }
            }
            if (best == d) {
                correct = correct + 1u;
            }
            conf_sum = conf_sum + exp(clamp(logits[base + d], -20.0, 0.0));
        }
    }
    let errors = total - correct;
    let has_errors = select(0u, 1u, errors > 0u);
    let acc = select(0.0, f32(correct) / f32(total), total > 0u);
    let mean_conf = select(0.0, conf_sum / f32(total), total > 0u);
    metrics[d] = DigitMetric(d, total, correct, errors, has_errors, acc, mean_conf);
}

// Place one label anchor just outside each digit column on the ring.
@compute @workgroup_size(10)
fn place_labels(@builtin(global_invocation_id) id: vec3<u32>) {
    let d = id.x;
    if (d >= CLASSES) {
        return;
    }
    labels[d] = Label(vec4<f32>(ring_pos(d, RING_R * 1.28, BASE_Y), 1.0), d);
}

instance.draw:
struct BarOut {
    @builtin(position) position: vec4<f32>,
    @location(0) color: vec4<f32>,
    @location(1) @interpolate(flat) item: u32,
}

// 36 unit-cube vertices (6 faces x 2 triangles) in [-0.5, 0.5] x [0, 1] x [-0.5, 0.5].
fn cube_vertex(v: u32) -> vec3<f32> {
    var pts = array<vec3<f32>, 36>(
        // +Z front
        vec3<f32>(-0.5, 0.0,  0.5), vec3<f32>( 0.5, 0.0,  0.5), vec3<f32>( 0.5, 1.0,  0.5),
        vec3<f32>(-0.5, 0.0,  0.5), vec3<f32>( 0.5, 1.0,  0.5), vec3<f32>(-0.5, 1.0,  0.5),
        // -Z back
        vec3<f32>( 0.5, 0.0, -0.5), vec3<f32>(-0.5, 0.0, -0.5), vec3<f32>(-0.5, 1.0, -0.5),
        vec3<f32>( 0.5, 0.0, -0.5), vec3<f32>(-0.5, 1.0, -0.5), vec3<f32>( 0.5, 1.0, -0.5),
        // +X right
        vec3<f32>( 0.5, 0.0,  0.5), vec3<f32>( 0.5, 0.0, -0.5), vec3<f32>( 0.5, 1.0, -0.5),
        vec3<f32>( 0.5, 0.0,  0.5), vec3<f32>( 0.5, 1.0, -0.5), vec3<f32>( 0.5, 1.0,  0.5),
        // -X left
        vec3<f32>(-0.5, 0.0, -0.5), vec3<f32>(-0.5, 0.0,  0.5), vec3<f32>(-0.5, 1.0,  0.5),
        vec3<f32>(-0.5, 0.0, -0.5), vec3<f32>(-0.5, 1.0,  0.5), vec3<f32>(-0.5, 1.0, -0.5),
        // +Y top
        vec3<f32>(-0.5, 1.0,  0.5), vec3<f32>( 0.5, 1.0,  0.5), vec3<f32>( 0.5, 1.0, -0.5),
        vec3<f32>(-0.5, 1.0,  0.5), vec3<f32>( 0.5, 1.0, -0.5), vec3<f32>(-0.5, 1.0, -0.5),
        // -Y bottom
        vec3<f32>(-0.5, 0.0, -0.5), vec3<f32>( 0.5, 0.0, -0.5), vec3<f32>( 0.5, 0.0,  0.5),
        vec3<f32>(-0.5, 0.0, -0.5), vec3<f32>( 0.5, 0.0,  0.5), vec3<f32>(-0.5, 0.0,  0.5),
    );
    return pts[min(v, 35u)];
}

fn face_shade(face: u32) -> f32 {
    var shades = array<f32, 6>(0.92, 0.72, 0.84, 0.76, 1.0, 0.62);
    return shades[min(face, 5u)];
}

fn digit_color(d: u32) -> vec3<f32> {
    var palette = array<vec3<f32>, 10>(
        vec3<f32>(0.22, 0.56, 0.96),
        vec3<f32>(0.18, 0.74, 0.68),
        vec3<f32>(0.64, 0.36, 0.94),
        vec3<f32>(0.20, 0.72, 0.38),
        vec3<f32>(0.88, 0.32, 0.48),
        vec3<f32>(0.28, 0.68, 0.92),
        vec3<f32>(0.54, 0.42, 0.92),
        vec3<f32>(0.16, 0.78, 0.56),
        vec3<f32>(0.84, 0.38, 0.66),
        vec3<f32>(0.34, 0.52, 0.96),
    );
    return palette[d % 10u];
}

@vertex
fn bar_vs(@builtin(instance_index) i: u32, @builtin(vertex_index) v: u32) -> BarOut {
    let m = metrics[i];
    let p = cube_vertex(v);
    let width = 0.28;
    let height = (0.14 + 1.35 * clamp(m.accuracy, 0.0, 1.0)) * params.scale;
    let a = digit_angle(m.digit);
    let ca = cos(a);
    let sa = sin(a);
    let lx = p.x * width;
    let ly = p.y * height;
    let lz = p.z * width;
    let rx = lx * ca - lz * sa;
    let rz = lx * sa + lz * ca;
    let world = ring_pos(m.digit, RING_R, BASE_Y) + vec3<f32>(rx, ly, rz);
    let shade = face_shade(v / 6u);
    var rgb = digit_color(m.digit) * shade;
    if (pick__selected(i)) {
        rgb = vec3<f32>(1.0, 0.86, 0.24) * (0.85 + 0.15 * shade);
    }
    var out: BarOut;
    out.position = camera__clip(world);
    out.color = vec4<f32>(rgb, 1.0);
    out.item = i;
    return out;
}

@fragment
fn bar_fs(in: BarOut) -> CaliperPicked {
    var out: CaliperPicked;
    out.color = in.color;
    out.id = pick__id(in.item);
    return out;
}
